const phaseActions={
  morning:'Morgenen brukes til å etablere sann operativ status før nye løfter gis: spilleren leser gjeldende produksjonsversjon, skiller planlagt fra bemannet, testet, frigitt og blokkert, og navngir riktig eier og neste kontroll. Dette er produksjonsarbeid, ikke en moralsk dom over hvem som virker mest lojal.',
  lunch:'Ved lunsj møtes ulike statuser i samme sak. Spilleren må oversette mellom teknikk, crew, stage management, artist eller hus uten å glatte over uenighet; sosial tyngde, kjendisstatus og hvem som faktisk har mandat skal forbli forskjellige ting.',
  afternoon:'Ettermiddagen tvinger frem en konkret replanlegging, beslutning eller handoff. Bare berørte ledd gjenåpnes, tidligere versjon bevares, ny forutsetning distribueres til de som faktisk trenger den, og status kan ikke bli grønn før kvalifikasjon, test, frigivelse eller bekreftet overtakelse finnes.',
  evening:'Kvelden viser den sosiale og private ettervirkningen av operativ beredskap. Spilleren ser hvem som bar ekstra belastning, hvordan feil og skam kan skjule avvik, hva som fortsatt venter, og om jobben begynner å spise søvn, identitet eller fortrolighet selv etter at radioen er slått av.'
};
const phaseType={morning:'task',lunch:'conversation',afternoon:'decision',evening:'private_consequence'};
const phases=['morning','lunch','afternoon','evening'];
const coverage=[];
for(let d=1;d<=14;d++) for(let p=0;p<4;p++){
  const phase=phases[p], arc=dayArcs[d-1], ref=refs[coverage.length%refs.length];
  const summary=`Dag ${d}, ${phase}: ${arc[0]} ${phaseActions[phase]} Produksjonsboken «produksjonsbok_kjoreplan_bemanning_sikkerhet_og_avvikslogg» er felles sannhetskilde for kjøreplanversjon, crew, kvalifikasjon, skift/hvile, teknisk test, stoppeier, husstatus, publikumsflyt, avvik, handoff, gjenopptakelse og debrief. Spilleren må bruke presise statusord—foreslått, besluttet, bemannet, testet, frigitt, distribuert, utført, avviket og lukket—slik at deadline, artiststatus, vennskap, lojalitet eller subkulturell kapital aldri kan late som formell sikkerhets-, arbeidsgiver- eller fagmyndighet. Når premisset endres, skal bare berørte ledd åpnes på nytt, men tidligere versjon og begrunnelse bevares slik at senere konsekvenser kan spores. Dagens beat er skrevet som operativt produksjonsarbeid, ikke som ny runtime-mekanikk, og materialiseres fra den eksisterende mailen ${ref.split('#')[1]}.`;
  const audience=audienceIds[(d+p-1)%audienceIds.length];
  const standing=`Standing hos ${audience} endres langsomt ut fra det som faktisk kan observeres i denne konkrete relasjonen: om status var sann, om spilleren respekterte faglig stopp og kvalifikasjon, om belastning og risiko ble synlig, og om handoffen gjorde neste kontroll mulig. Et godt resultat kan derfor øke tillit hos crew samtidig som artist eller program er frustrert over redusert tempo; det er nettopp poenget med situert standing. Ingen slik standing kan gi teknisk frigivelse, HMS-dispensasjon, arbeidsgiverfullmakt, medisinsk eller juridisk vurdering, rettighetsklarering eller rett til å ansette, sanksjonere eller omgå husets formelle rammer. Hvis spilleren skjuler et avvik for å beskytte tidsplan eller ansikt, lagres konsekvensen redaksjonelt som senere sosialt og profesjonelt press; hvis spilleren varsler tidlig og avgrenser rework, blir produksjonen mer reparerbar uten at konflikten forsvinner magisk.`;
  coverage.push({day:d,phase,beat_type:phaseType[phase],summary,thread_ids:[arc[1]],materialization_refs:[ref],standing_audience:audience,standing_consequence:standing});
}

